   506		// Handle added routes based on trailing slash:
   507		// 	/prefix  => exact route "/prefix" + any route "/prefix/*"
   508		// 	/prefix/ => only any route "/prefix/*"
   509		if prefix != "" {
   510			if prefix[len(prefix)-1] == '/' {
   511				// Only add any route for intentional trailing slash
   512				return get(prefix+"*", h)
   513			}
   514			get(prefix, h)
   515		}
   516		return get(prefix+"/*", h)
   517	}
