   966	func newListener(address, network string) (*tcpKeepAliveListener, error) {
   967		if network != "tcp" && network != "tcp4" && network != "tcp6" {
   968			return nil, ErrInvalidListenerNetwork
   969		}
   970		l, err := net.Listen(network, address)
   971		if err != nil {
   972			return nil, err
   973		}
   974		return &tcpKeepAliveListener{l.(*net.TCPListener)}, nil
   975	}
