func TestTmpScheme(t *testing.T) {
	tests := []struct {
		name    string
		header  http.Header
		tls     bool
		expect  string
	}{
		{
			name:   "X-Forwarded-Proto ftp + X-Url-Scheme https",
			header: http.Header{HeaderXForwardedProto: []string{"ftp"}, HeaderXUrlScheme: []string{"https"}},
			expect: "https",
		},
		{
			name:   "X-Forwarded-Proto ftp alone",
			header: http.Header{HeaderXForwardedProto: []string{"ftp"}},
			expect: "http",
		},
		{
			name:   "X-Forwarded-Proto https",
			header: http.Header{HeaderXForwardedProto: []string{"https"}},
			expect: "https",
		},
		{
			name:   "X-Forwarded-Protocol http",
			header: http.Header{HeaderXForwardedProtocol: []string{"http"}},
			expect: "http",
		},
		{
			name:   "X-Forwarded-Ssl on",
			header: http.Header{HeaderXForwardedSsl: []string{"on"}},
			expect: "https",
		},
		{
			name:   "X-Url-Scheme https",
			header: http.Header{HeaderXUrlScheme: []string{"https"}},
			expect: "https",
		},
		{
			name:   "no headers",
			header: http.Header{},
			expect: "http",
		},
		{
			name:   "TLS set",
			header: http.Header{},
			tls:    true,
			expect: "https",
		},
		{
			name:   "X-Forwarded-Proto ftp + X-Forwarded-Protocol http",
			header: http.Header{HeaderXForwardedProto: []string{"ftp"}, HeaderXForwardedProtocol: []string{"http"}},
			expect: "http",
		},
		{
			name:   "X-Forwarded-Proto ftp + X-Forwarded-Ssl on",
			header: http.Header{HeaderXForwardedProto: []string{"ftp"}, HeaderXForwardedSsl: []string{"on"}},
			expect: "https",
		},
		{
			name:   "all ftp",
			header: http.Header{HeaderXForwardedProto: []string{"ftp"}, HeaderXForwardedProtocol: []string{"ftp"}, HeaderXUrlScheme: []string{"ftp"}},
			expect: "http",
		},
	}

	for _, tt := range tests {
		req := &http.Request{Header: tt.header}
		if tt.tls {
			req.TLS = &tls.ConnectionState{}
		}
		c := &context{request: req}
		if got := c.Scheme(); got != tt.expect {
			t.Errorf("%s: got %q, want %q", tt.name, got, tt.expect)
		}
	}
}

