func TestTmpBindMap(t *testing.T) {
	e := New()
	req := httptest.NewRequest(http.MethodGet, "/?tag=a&tag=b&id=1", nil)
	c := e.NewContext(req, httptest.NewRecorder())

	m := map[string][]string{}
	if err := c.Bind(&m); err != nil {
		t.Fatalf("map[string][]string: unexpected error: %v", err)
	}
	want := map[string][]string{"tag": {"a", "b"}, "id": {"1"}}
	if !reflect.DeepEqual(m, want) {
		t.Fatalf("map[string][]string: got %#v want %#v", m, want)
	}

	var m2 map[string][]string
	if err := c.Bind(&m2); err != nil {
		t.Fatalf("nil map[string][]string: unexpected error: %v", err)
	}
	if !reflect.DeepEqual(m2, want) {
		t.Fatalf("nil map[string][]string: got %#v want %#v", m2, want)
	}

	m3 := map[string]string{}
	if err := c.Bind(&m3); err != nil {
		t.Fatalf("map[string]string: unexpected error: %v", err)
	}
	if m3["tag"] != "a" {
		t.Fatalf("map[string]string: got %#v", m3)
	}

	m4 := map[string]interface{}{}
	if err := c.Bind(&m4); err != nil {
		t.Fatalf("map[string]interface{}: unexpected error: %v", err)
	}
	if !reflect.DeepEqual(m4["tag"], []string{"a", "b"}) {
		t.Fatalf("map[string]interface{}: got %#v", m4["tag"])
	}

	m5 := map[string]int{}
	if err := c.Bind(&m5); err != nil {
		t.Fatalf("map[string]int: unexpected error: %v", err)
	}
	if m5["id"] != 1 {
		t.Fatalf("map[string]int: got %#v", m5)
	}
}

